def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            top = min(y for y, x in comp)
            bottom = max(y for y, x in comp)
            left = min(x for y, x in comp)
            right = max(x for y, x in comp)
            top_cells = {x for y, x in comp if y == top}
            gaps = [x for x in range(left, right + 1) if x not in top_cells]
            if not gaps:
                continue

            gap = gaps[0]
            left_run = sum(1 for x in range(left, gap) if x in top_cells)
            right_run = sum(1 for x in range(gap + 1, right + 1) if x in top_cells)
            direction = -1 if left_run > right_run else 1

            out[top][gap] = 2
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    if out[y][x] == 0:
                        out[y][x] = 2

            beam_row = top - 1
            if beam_row >= 0:
                x = gap
                while 0 <= x < w:
                    if out[beam_row][x] == 0:
                        out[beam_row][x] = 2
                    x += direction

    return out
